-- ============================================================
-- CERT 2: Revolving Loan Fund Design & Capitalization
-- ============================================================
DO $$
DECLARE
  cert_id uuid; m1 uuid; m2 uuid; m3 uuid; m4 uuid; m5 uuid; quiz_id uuid;
BEGIN
  SELECT id INTO cert_id FROM certifications WHERE cert_number = 2;
  IF cert_id IS NULL THEN RAISE NOTICE 'Cert 2 not found'; RETURN; END IF;

  UPDATE certifications SET status = 'approved', learning_outcomes = ARRAY[
    'Explain the RLF capital cycle and how revolving funds sustain themselves over time',
    'Design fund purpose, eligible borrowers, eligible uses, loan terms, and pricing',
    'Build a capitalization plan using RBDG, RMAP, IRP, EDA, CDFI, and philanthropic sources',
    'Understand the federal cost share requirement and non-federal match options',
    'Create a basic 3-year RLF pro forma showing sustainability',
    'Structure loan committee governance, conflict of interest policy, and written loan policies'
  ] WHERE id = cert_id;

  INSERT INTO modules (id, certification_id, title, sort_order, status) VALUES
    (gen_random_uuid(), cert_id, 'How Revolving Loan Funds Work', 1, 'approved'),
    (gen_random_uuid(), cert_id, 'Designing Your Loan Products', 2, 'approved'),
    (gen_random_uuid(), cert_id, 'Capitalization Strategy', 3, 'approved'),
    (gen_random_uuid(), cert_id, 'Governance and Written Policies', 4, 'approved'),
    (gen_random_uuid(), cert_id, 'Financial Sustainability', 5, 'approved')
  ON CONFLICT DO NOTHING;

  SELECT id INTO m1 FROM modules WHERE certification_id = cert_id AND sort_order = 1;
  SELECT id INTO m2 FROM modules WHERE certification_id = cert_id AND sort_order = 2;
  SELECT id INTO m3 FROM modules WHERE certification_id = cert_id AND sort_order = 3;
  SELECT id INTO m4 FROM modules WHERE certification_id = cert_id AND sort_order = 4;
  SELECT id INTO m5 FROM modules WHERE certification_id = cert_id AND sort_order = 5;

  -- Module 1 Lessons
  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m1, 'The RLF Capital Cycle', 'cert02-rlf-capital-cycle',
  E'## What Is a Revolving Loan Fund?\n\nA revolving loan fund (RLF) is a pool of capital that is lent to borrowers, repaid over time, and then lent again — revolving continuously rather than being spent once like a grant. This self-renewing structure is what makes RLFs fundamentally different from grants and why they are so valuable for rural economic development.\n\n## Tracing a Dollar Through the Fund\n\nUnderstanding the capital cycle is essential for anyone designing or operating an RLF:\n\n**Step 1 — Capitalization:** Money enters the fund from one or more sources: a USDA RBDG grant, a USDA RMAP loan, an EDA grant, philanthropic gifts, or bank investments. This capital sits in an interest-bearing fund account.\n\n**Step 2 — Origination:** A small business applies for a loan. The fund underwrites the application against written credit criteria. The loan committee approves. The loan is closed and disbursed.\n\n**Step 3 — Servicing:** The borrower makes monthly principal and interest payments. Principal payments return to the fund. Interest income covers operating costs and builds reserves.\n\n**Step 4 — Relending:** When enough principal has returned, the fund makes another loan. Over time, the same dollar is lent and repaid multiple times — multiplying its economic impact without requiring new grants.\n\n## The RMRF Structure Under RMAP\n\nUnder the USDA Rural Microentrepreneur Assistance Program, the RLF is called a **Rural Microloan Revolving Fund (RMRF)**. Key features:\n\n- The RMRF is an **exclusive, interest-bearing account** — program funds cannot be commingled with operating accounts\n- USDA holds a **first lien** on the RMRF\n- Microloans made from the RMRF cannot exceed **$50,000** per borrower\n- Loan terms may not exceed **10 years**\n- Interest rates must be **fixed** at origination\n\nAlongside the RMRF, every RMAP microlender must maintain a **Loan Loss Reserve Fund (LLRF)** — a separate interest-bearing account equal to at least **5% of the total amount owed to USDA**. The LLRF absorbs delinquency losses before they impact the RMRF.\n\n## RLF vs. Grant: The Core Difference\n\n| Feature | Grant | Revolving Loan Fund |\n|---------|-------|--------------------|\n| Spent once | Yes | No — revolves |\n| Returns to fund | No | Yes — principal repayments |\n| Leverage ratio | 1:1 | 3:1 to 10:1 over time |\n| Federal reporting | Yes | Yes |\n| Sustainability | Ends when funds run out | Self-sustaining with good management |\n\nA well-managed RLF can multiply its original capital 3 to 10 times over a decade. A $500,000 RBDG-capitalized RLF that averages 18-month loan terms can deploy $1.5 million or more in its first five years.',
  'Understand the RLF capital cycle, RMRF/LLRF structure, and why revolving funds multiply impact.', 16, 1, 'approved'),

  (m1, 'Types of RLFs and Capitalization Sources', 'cert02-rlf-types',
  E'## Federal RLF Programs\n\nSeveral federal programs capitalize revolving loan funds. Understanding each source — its rules, requirements, and appropriate use — is essential for building a sustainable capital strategy.\n\n### USDA RBDG (Rural Business Development Grant)\n**What it is:** A competitive grant that can be used to establish or recapitalize an RLF for rural small businesses.\n**Who can apply:** Rural public entities, nonprofits, and Federally-recognized Indian tribes.\n**Loan size:** The resulting RLF loans can be larger than RMAP microloans — no hard cap in the RBDG regulation itself, though the grant amount limits scale.\n**Best for:** Organizations starting their first RLF — RBDG is grant capital, so there is no repayment obligation to USDA for the fund itself.\n**Key rule:** RBDG RLF loans must serve rural small businesses and must generate or retain jobs.\n\n### USDA RMAP (Rural Microentrepreneur Assistance Program)\n**What it is:** A direct loan (not a grant) from USDA to an MDO to capitalize an RMRF for microloans.\n**Loan cap:** $50,000 per microborrower, 10-year max term, fixed rate.\n**Key distinction:** RMAP is a loan to the microlender — the microlender owes USDA the principal and must repay it from RMRF repayments. This is not free capital.\n**Best for:** Organizations with demonstrated microlending experience seeking to scale.\n\n### USDA IRP (Intermediary Relending Program)\n**What it is:** Low-interest USDA loans to intermediaries (CDFIs, nonprofits, public bodies) that re-lend to rural businesses and communities.\n**Loan size:** Larger than RMAP — IRP intermediary loans can be up to $1 million to $2 million from USDA, enabling larger portfolio capacity.\n**Best for:** Organizations with strong financial history, federal compliance experience, and existing loan portfolios ready to scale into business loans beyond microenterprise.\n\n### EDA Revolving Loan Fund Program\n**What it is:** Economic Development Administration grants to establish or recapitalize RLFs for economic distress areas.\n**Eligibility:** Areas with high unemployment, low income, or economic distress as defined by EDA.\n**Best for:** Organizations in economically distressed rural communities — EDA has geographic targeting requirements.\n\n### CDFI Fund Awards\n**What it is:** CDFI Fund Financial Assistance (FA) awards provide capital and technical assistance to CDFIs and emerging CDFIs.\n**Best for:** Organizations seeking CDFI certification as part of their strategy — CDFI FA awards can capitalize lending programs and count as non-federal match for USDA programs.\n\n### Other Sources\n- **Bank CRA investments** — Community Reinvestment Act lending, investment, or service credit motivates banks to invest in CDFI/RLF programs\n- **State rural development funds** — Many states have their own RLF programs or matching grant programs\n- **Philanthropic capital** — Foundation grants, program-related investments (PRIs), and mission-related investments\n- **Program income** — Interest earned and fees from the RLF itself can be reinvested',
  'Survey all federal and non-federal RLF capitalization sources, their rules, and best use cases.', 14, 2, 'approved')

  ON CONFLICT DO NOTHING;

  -- Module 2 Lessons
  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m2, 'Designing Your Loan Products', 'cert02-loan-products',
  E'## The Loan Product Design Decision\n\nYour loan product defines what your RLF does and for whom. A well-designed loan product serves your target borrowers, satisfies funder requirements, and can be administered with your available staff capacity. Vague loan products create compliance risk and inconsistent decision-making.\n\n## Core Loan Product Parameters\n\n### Target Market\nDefine who you serve before you define the loan. Your target market should include:\n- Business type (microenterprise, small business, agricultural producer)\n- Geographic area (specific counties, rural areas as defined by USDA)\n- Stage of business (startup, early-stage, established)\n- Population served (minority-owned, women-owned, returning citizens, tribal members)\n\nYour target market drives every other product decision.\n\n### Loan Size Range\nSet a minimum and maximum loan size. For RMAP: maximum $50,000 per borrower. For RBDG RLFs: based on your fund size and underwriting capacity. Common microloan ranges: $500 to $50,000.\n\n**Rule of thumb:** Your average loan size should be no more than 10-15% of your total fund capital to maintain adequate portfolio diversification.\n\n### Interest Rate Policy\nFor RMAP: rate must be fixed. For other RLFs: you may offer variable or fixed. Consider:\n- Your cost of funds (what you owe USDA or other lenders)\n- Your administrative cost per loan\n- Your loss reserve contribution\n- Market rates for comparable credit\n\nA common structure: cost of funds + 2-4% spread = borrower rate. This spread covers administration and reserves.\n\n### Term Limits\n\n| Loan Purpose | Suggested Maximum Term |\n|-------------|------------------------|\n| Working capital | 12-36 months |\n| Equipment (5-7 year life) | 48-84 months |\n| Leasehold improvements | 36-60 months |\n| Business acquisition | 60-120 months |\n\nFor RMAP: maximum 10-year term regardless of purpose.\n\n### Eligible and Ineligible Uses\n**Eligible uses (examples):** equipment purchase, inventory, working capital, leasehold improvements, business acquisition, operating expenses.\n\n**Ineligible uses under RMAP:**\n- Residential housing construction or rehabilitation\n- Lines of credit (revolving credit lines)\n- Agricultural production (unless meeting microenterprise definition)\n- Loans to insiders (officers, directors, employees of the MDO)\n- Religious activities as primary purpose\n- Gambling or illegal activities\n- Businesses outside the eligible rural area\n\n## The Loan Product Matrix\n\nDocument your loan products in a single reference table:\n\n| Parameter | Microloan Product | Notes |\n|-----------|------------------|-------|\n| Loan size | $1,000 – $50,000 | RMAP maximum |\n| Term | Up to 10 years | Matched to use |\n| Rate | Fixed, set at closing | Based on cost of funds |\n| Eligible uses | Equipment, WC, improvements | Per written policy |\n| Collateral | Required > $10,000 | UCC filing |\n| Credit score | No minimum | Capacity-based |\n| TA required | Yes | Pre and post-loan |',
  'Design loan product parameters: target market, loan size, rate, term, eligible uses, collateral.', 18, 1, 'approved'),

  (m2, 'Defining Your Service Area and Fund Purpose', 'cert02-service-area',
  E'## Why Your Fund Purpose Statement Matters\n\nYour fund purpose statement is not marketing copy. It is a governance document that:\n- Defines what loans you can make (and what you cannot)\n- Guides your loan committee in borderline decisions\n- Satisfies federal funder requirements for program description\n- Appears verbatim in your RMAP application (scored up to 5 points)\n\nA weak purpose statement ("to help businesses in our area") gives your loan committee no guidance and scores poorly. A strong purpose statement is specific, rural-aligned, and mission-driven.\n\n## Writing a Strong Purpose Statement\n\n**Weak:** "To provide loans to small businesses in our community."\n\n**Strong:** "The [Organization] Revolving Loan Fund provides fixed-rate microloans of $1,000 to $50,000 to rural microenterprises located in [County/Region], with priority given to businesses owned by racial and ethnic minorities, women, and returning citizens, that are unable to obtain sufficient credit from conventional sources. Loans are paired with technical assistance and business coaching to improve borrower readiness and repayment success."\n\nNotice what the strong version includes:\n- Loan size range\n- Geographic area (rural)\n- Priority populations\n- Credit elsewhere standard\n- Connection to TA\n\n## Defining Your Geographic Service Area for USDA Eligibility\n\nAll USDA RMAP and RBDG programs require that borrowers and the service area be **rural** as defined in 7 CFR 4280:\n\n> "Any area of a state not in a city or town that has a population of more than 50,000 inhabitants, according to the latest applicable decennial census."\n\nTo document your service area:\n1. List the counties or jurisdictions you will serve\n2. Verify each county seat population using the most recent Census data\n3. For mixed rural/urban counties: identify the rural portions specifically\n4. Map your service area — a simple county map with shading works\n\nUSDA does not score you on how large your service area is. They score you on your **ability to cover** the area you describe. A two-county rural service area you can fully serve scores better than a 20-county area you cannot.\n\n## Common Service Area Mistakes\n\n- **Claiming urban areas:** If you serve a county with a city over 50,000, document that your lending is restricted to the rural portions\n- **Over-promising geography:** Do not claim a 15-county service area if you have one loan officer\n- **Inconsistency:** Your service area in the RMAP application must match your written loan policy and your geographic data in the scoring tables',
  'Write a strong fund purpose statement and define a USDA-eligible rural service area.', 14, 2, 'approved')

  ON CONFLICT DO NOTHING;

  -- Module 3 Lessons
  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m3, 'Building Your Capital Stack', 'cert02-capital-stack',
  E'## What Is a Capital Stack?\n\nA capital stack is the combination of funding sources that together capitalize your RLF. Almost no rural microlending organization relies on a single source. The most sustainable RLFs blend federal program capital with philanthropic grants, bank CRA investments, and program income.\n\n## Sequencing Your Capital Sources\n\nThe order in which you pursue capital matters:\n\n**Phase 1 — Establish with grant capital (Year 1-2)**\nStart with sources that do not require repayment from the RLF itself. RBDG is the ideal first capital because it is a grant — the fund does not owe USDA repayment. CDFI Fund FA awards and philanthropic PRIs also fit here.\n\nWhy start with grants? Because grant capital absorbs losses without threatening your ability to repay a federal lender. Starting with a loan program (RMAP) before you have proven your portfolio creates risk if early loans default.\n\n**Phase 2 — Add RMAP when microlending capacity is proven (Year 2-4)**\nOnce you have 12-24 months of microloan history showing low delinquency and strong TA delivery, apply for RMAP. Your track record becomes your scoring evidence.\n\nRemember: RMAP is a loan to your organization. You owe USDA the principal. Every microloan default that is not covered by your LLRF reduces the fund available to repay USDA.\n\n**Phase 3 — Layer IRP for expanded capacity (Year 4+)**\nIRP provides low-interest capital to qualified intermediaries for business loans that may be larger than RMAP microloans. By the time you apply for IRP, you should have strong financials, a proven portfolio, full written policies, and experience managing federal program compliance.\n\n## The Federal Cost Share Requirement\n\nAll RMAP loans to microlenders require a **25% non-federal match**:\n\n- **Project-level option:** Each individual microloan is capped at 75% of project cost; the borrower provides 25% from non-federal sources\n- **Fund-level option:** The RMRF itself is capitalized with at least 25% non-federal funds, allowing 100% financing of individual microborrower projects\n\nNon-federal match can come from: philanthropic grants, bank CRA investments, state funds, program income, or organizational equity — anything that is not a federal program.\n\n## Building Your Capitalization Roadmap\n\nYour roadmap should show:\n- Current capital sources and amounts\n- Target capital needed for Years 1, 3, and 5\n- Specific funders you will pursue in each phase\n- Non-federal match sources and amounts\n- Projected loan volume at each phase\n- Assumptions: average loan size, term, default rate\n\nThis roadmap becomes a required artifact in both RBDG and RMAP applications.',
  'Sequence capital sources strategically: RBDG first, then RMAP, then IRP. Understand the 25% match requirement.', 16, 1, 'approved')

  ON CONFLICT DO NOTHING;

  -- Module 4 Lessons
  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m4, 'Loan Committee Governance', 'cert02-loan-committee',
  E'## Why Governance Matters for RLFs\n\nFederal funders — especially USDA — expect to see that loan decisions are made through a documented, conflict-free process. Loan committee governance is scored directly in RMAP applications (up to 5 points under the policy and procedures criterion) and is audited during USDA oversight visits.\n\nPoor governance — verbal approvals, no minutes, committee members approving loans to family members — creates compliance findings that can jeopardize your RMAP agreement.\n\n## Loan Committee Structure\n\n**Who serves:** A loan committee typically includes 3-7 members with expertise in lending, small business, finance, law, or the communities you serve. Members may be board members, community volunteers, or external experts.\n\n**Key rule:** Loan committee members must not vote on any loan in which they have a personal or financial interest. This is the conflict of interest standard.\n\n**Quorum:** Define the minimum number of members required to make a binding decision (commonly 3 of 5, or a simple majority).\n\n**Authority levels:** Common structures:\n- Loan officer: approval authority for loans under $5,000\n- Loan committee: approval authority for loans $5,001 to $50,000\n- Board: approval authority for loans above cap or exceptions to policy\n\n## Conflict of Interest Policy\n\nEvery RLF needs a written conflict of interest policy that:\n1. Defines what constitutes a conflict (personal relationship, financial interest, employment)\n2. Requires members to disclose conflicts before each meeting\n3. Requires conflicted members to recuse and leave the room during discussion and vote\n4. Documents recusals in the minutes\n\nFor USDA programs: the MDO itself cannot lend to its own officers, directors, or employees (insider loans are ineligible uses).\n\n## Meeting Minutes Standards\n\nEvery loan committee meeting must be documented with minutes that include:\n- Date, location, attendees, quorum confirmation\n- Loans presented: borrower name (or ID), amount, purpose, term, rate\n- Disclosures of conflict (or confirmation of none)\n- Motion, vote, and outcome for each loan\n- Any conditions attached to approval\n- Signature of committee chair or secretary\n\nMinutes must be maintained for the duration of the USDA program agreement plus the required record retention period (typically 3-7 years after program closeout).',
  'Structure a compliant loan committee with proper authority, conflict of interest policy, and minutes documentation.', 15, 1, 'approved'),

  (m4, 'Writing Your Loan Fund Policies', 'cert02-loan-policies',
  E'## Why Written Policies Are Non-Negotiable\n\nFor USDA RMAP applications, written policies are required — not optional. Section 4280.316(a)(4) requires applicants to provide "those parts of your policy and procedures manual that deal with the provision of loans, management of loan funds, and provision of technical assistance." Points are awarded based on the quality of those policies.\n\nBeyond RMAP, written policies:\n- Create consistency in decision-making (every loan officer applies the same standards)\n- Protect the organization from discrimination claims (uniform criteria)\n- Satisfy auditors that the organization has internal controls\n- Guide the loan committee when facing borderline applications\n\n## Required Policy Sections\n\nA compliant RLF policy manual should include at minimum:\n\n**1. Fund Purpose and Objectives**\nWho the fund serves, what it finances, and why the organization provides this capital.\n\n**2. Eligible Borrowers**\nEntity types, geographic eligibility, business stage requirements, credit elsewhere standard.\n\n**3. Eligible and Ineligible Uses**\nSpecific list of what the fund will and will not finance.\n\n**4. Loan Products**\nSize range, terms, rates, fees, and collateral requirements for each product.\n\n**5. Underwriting Standards**\nHow creditworthiness is evaluated: cash flow analysis, collateral requirements, credit history approach, personal guarantee requirements.\n\n**6. Loan Approval Authority**\nWho can approve what, quorum requirements, conditions authority.\n\n**7. Conflict of Interest**\nDefinition, disclosure requirements, recusal process.\n\n**8. TA Requirements**\nWhat TA is required before and after loan closing.\n\n**9. Servicing and Collections**\nPayment processing, delinquency escalation, workout authority.\n\n**10. Default and Charge-Off**\nDefault definition, charge-off authority, loss reserve draw procedure.\n\n## Policy Approval and Updates\n\nYour board must formally approve the loan policy. Document approval in board minutes. Establish an annual policy review cycle — review policies at least once per year and update as regulations, fund conditions, or best practices change. Date and version each revision.',
  'Write the required RLF policy manual sections for USDA compliance and consistent loan decision-making.', 14, 2, 'approved')

  ON CONFLICT DO NOTHING;

  -- Module 5 Lessons
  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m5, 'RLF Financial Sustainability and Pro Forma', 'cert02-pro-forma',
  E'## What Does a Sustainable RLF Look Like?\n\nA sustainable RLF generates enough income from interest and fees to cover its operating costs — loan origination, servicing, TA delivery, compliance, and reserves — without requiring continuous grant infusions. This does not happen automatically. It requires deliberate financial modeling.\n\n## The Four Sources of RLF Income\n\n1. **Interest income** — The spread between what you earn on microloans and what you owe on your USDA or other funding source\n2. **Origination and servicing fees** — One-time fees at closing and/or annual servicing fees\n3. **Program income from RMRF** — Interest earned on the uninvested RMRF balance\n4. **Grant income** — Administrative grants from funders to cover program costs (not a sustainable long-term strategy but common in early years)\n\n## The Three Cost Drivers\n\n1. **Loan origination costs** — Staff time to process applications, underwrite, close, and document loans\n2. **Servicing costs** — Payment processing, delinquency management, annual reviews, reporting\n3. **TA and program costs** — Business coaching, group training, TA partner contracts\n\n## Building a 3-Year Pro Forma\n\nA basic RLF pro forma models:\n\n| Item | Year 1 | Year 2 | Year 3 |\n|------|--------|--------|--------|\n| Fund capital available | $500,000 | $520,000 | $560,000 |\n| Loans originated | $150,000 | $200,000 | $250,000 |\n| Average loan size | $15,000 | $15,000 | $18,000 |\n| Average interest rate | 6% | 6% | 6% |\n| Gross interest income | $9,000 | $13,500 | $18,000 |\n| Loss reserve contribution (2%) | -$3,000 | -$4,000 | -$5,000 |\n| Administrative costs | -$80,000 | -$85,000 | -$90,000 |\n| Grant income needed | $74,000 | $75,500 | $77,000 |\n\nThis shows a small fund that still requires grant support in Year 3. To reach self-sufficiency, you need either:\n- A much larger loan portfolio (higher volume means more interest income)\n- Lower administrative costs per loan\n- Higher interest rates (within responsible pricing limits)\n- Sustained administrative grant support\n\n**Rule of thumb for RMAP:** At $50,000 average loan size and 6% rate, you need approximately $2 million in outstanding loans to generate $120,000 in gross interest income — enough to begin covering administrative costs.',
  'Model RLF financial sustainability using a 3-year pro forma covering income, costs, and grant dependency.', 15, 1, 'approved')

  ON CONFLICT DO NOTHING;

  -- Quiz
  INSERT INTO quizzes (id, certification_id, title, passing_score, status)
  VALUES (gen_random_uuid(), cert_id, 'RLF Design & Capitalization Knowledge Check', 80, 'approved')
  ON CONFLICT DO NOTHING;
  SELECT id INTO quiz_id FROM quizzes WHERE certification_id = cert_id;

  INSERT INTO quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES
  (quiz_id, 'What makes a revolving loan fund different from a grant?', '[{"id":"a","text":"RLFs charge higher interest than grants"},{"id":"b","text":"Principal repayments return to the fund and are lent again, multiplying impact over time"},{"id":"c","text":"RLFs are managed by the government, grants are managed by nonprofits"},{"id":"d","text":"Grants can only be used for equipment while RLFs fund any purpose"}]', 'b', 'The revolving mechanism — principal repayments returning to the fund — is what distinguishes an RLF from a grant. The same capital can be deployed multiple times, multiplying economic impact without new grants.', 1),
  (quiz_id, 'Under USDA RMAP, what is the minimum Loan Loss Reserve Fund (LLRF) balance required?', '[{"id":"a","text":"2% of total outstanding microloans"},{"id":"b","text":"5% of the total amount owed by the microlender to USDA"},{"id":"c","text":"10% of the RMRF balance"},{"id":"d","text":"3% of annual loan originations"}]', 'b', 'The LLRF must be maintained at not less than 5% of the total amount owed to USDA. It absorbs delinquency losses before they impact the RMRF.', 2),
  (quiz_id, 'Which federal program is generally recommended as FIRST capital for a new RLF because it does not require repayment to USDA?', '[{"id":"a","text":"RMAP"},{"id":"b","text":"IRP"},{"id":"c","text":"RBDG"},{"id":"d","text":"CDFI Fund FA"}]', 'c', 'RBDG is a grant — the organization does not owe USDA repayment from the fund. RMAP and IRP are loans to the microlender, creating repayment obligations that are risky for unproven programs.', 3),
  (quiz_id, 'The RMAP federal cost share requirement means:', '[{"id":"a","text":"50% of the RMRF must come from federal sources"},{"id":"b","text":"At least 25% of the eligible project cost must come from non-federal sources"},{"id":"c","text":"The microlender must match every USDA dollar with two non-federal dollars"},{"id":"d","text":"All RMRF funds must be matched by state government"}]', 'b', 'The federal share may not exceed 75% of eligible project cost. The remaining 25% must come from non-federal sources — met either at the project level or the RMRF capitalization level.', 4),
  (quiz_id, 'Which of the following is an INELIGIBLE use of RMAP microloan funds?', '[{"id":"a","text":"Equipment purchase for a rural food truck"},{"id":"b","text":"Working capital for a rural retailer"},{"id":"c","text":"A revolving line of credit for a rural landscaper"},{"id":"d","text":"Leasehold improvements for a rural salon"}]', 'c', 'Revolving lines of credit are ineligible under RMAP. RMAP microloans must be for a defined purpose. Other ineligible uses include residential housing, insider transactions, and religious activities.', 5),
  (quiz_id, 'What is the maximum loan term for an RMAP microloan?', '[{"id":"a","text":"5 years"},{"id":"b","text":"7 years"},{"id":"c","text":"10 years"},{"id":"d","text":"15 years"}]', 'c', 'RMAP microloans have a maximum term of 10 years. The interest rate must be fixed at origination.', 6),
  (quiz_id, 'For USDA eligibility, a "rural area" is defined as:', '[{"id":"a","text":"Any area with fewer than 25,000 residents"},{"id":"b","text":"Any county classified as rural by the state government"},{"id":"c","text":"Any area not in a city or town with more than 50,000 inhabitants per the latest decennial census"},{"id":"d","text":"Any area more than 50 miles from a major metropolitan center"}]', 'c', 'Under 7 CFR 4280, rural area means any area of a state not in a city or town that has a population of more than 50,000 inhabitants according to the latest applicable decennial census.', 7),
  (quiz_id, 'A strong fund purpose statement should include:', '[{"id":"a","text":"The organization''s full history and list of board members"},{"id":"b","text":"Loan size range, geographic area, target borrowers, and connection to TA"},{"id":"c","text":"A general statement about helping businesses in the community"},{"id":"d","text":"The names of all banks that declined to serve the area"}]', 'b', 'A strong purpose statement is specific: it includes loan size range, geographic area (rural), target borrowers, credit elsewhere standard, and the connection to technical assistance.', 8),
  (quiz_id, 'USDA scores your geographic service area based on:', '[{"id":"a","text":"The size of the area — larger is always better"},{"id":"b","text":"The number of counties included"},{"id":"c","text":"Your demonstrated ability to fully cover the service area you describe"},{"id":"d","text":"Whether your service area includes at least one distressed county"}]', 'c', 'USDA does not score on geographic size. They score on your ability to fully cover the area you describe. A two-county area you can genuinely serve scores better than a 20-county area you cannot staff.', 9),
  (quiz_id, 'The Intermediary Relending Program (IRP) is best pursued when:', '[{"id":"a","text":"An organization is brand new and needs startup capital"},{"id":"b","text":"An organization has a proven portfolio, strong financials, and systems for managing federal compliance"},{"id":"c","text":"An organization wants to avoid USDA reporting requirements"},{"id":"d","text":"An organization does not qualify for RMAP"}]', 'b', 'IRP is designed for experienced intermediaries. By the time an organization applies for IRP, they should have demonstrated financial strength, portfolio management experience, and federal compliance capacity.', 10),
  (quiz_id, 'What is the primary purpose of a loan committee conflict of interest policy?', '[{"id":"a","text":"To prevent board members from serving on the loan committee"},{"id":"b","text":"To ensure that members with personal or financial interests in a loan recuse themselves from that decision"},{"id":"c","text":"To limit the number of loans approved per quarter"},{"id":"d","text":"To require approval from the state government for large loans"}]', 'b', 'The conflict of interest policy requires members who have a personal or financial stake in a loan to disclose the conflict, recuse themselves, and leave the room during discussion and vote. This protects the integrity of credit decisions.', 11),
  (quiz_id, 'Which of the following loan purposes would you match with a 7-year maximum term?', '[{"id":"a","text":"Working capital for seasonal inventory"},{"id":"b","text":"Equipment with a 5-7 year useful economic life"},{"id":"c","text":"Business acquisition"},{"id":"d","text":"A 30-day operating bridge loan"}]', 'b', 'Loan term should match the economic life of the asset financed. Equipment with a 5-7 year useful life is appropriately matched with a 48-84 month term. Working capital should be shorter (12-36 months).', 12),
  (quiz_id, 'To reach financial sustainability, a small RLF typically needs:', '[{"id":"a","text":"A minimum of $50,000 in outstanding loans"},{"id":"b","text":"A large enough loan portfolio so interest income covers operating costs — often $1-2 million or more in outstanding balances"},{"id":"c","text":"At least 10 years of operation before any financial review"},{"id":"d","text":"A for-profit co-lender to share administrative costs"}]', 'b', 'Financial sustainability requires interest income sufficient to cover administrative costs. For a small fund at 6% rates, reaching $1-2 million in outstanding loans is a common threshold for meaningful self-sufficiency.', 13),
  (quiz_id, 'The RMRF under RMAP must be:', '[{"id":"a","text":"A checking account at any local bank"},{"id":"b","text":"An exclusive interest-bearing account with USDA holding a first lien"},{"id":"c","text":"Commingled with the organization''s operating account for efficiency"},{"id":"d","text":"Managed by a third-party trustee approved by the state"}]', 'b', 'The RMRF must be an exclusive interest-bearing account — no commingling with operating funds. USDA holds a first lien on the RMRF as security for the USDA loan.', 14),
  (quiz_id, 'Which of the following best describes program income for an RLF?', '[{"id":"a","text":"Grants received from the state government"},{"id":"b","text":"Interest income, origination fees, and servicing fees generated by the loan fund''s own activities"},{"id":"c","text":"Donations from local businesses and individuals"},{"id":"d","text":"Federal reimbursements for allowable administrative costs"}]', 'b', 'Program income is income generated by the federally-funded program itself — in an RLF context, this is primarily interest income, origination fees, and servicing fees from the loan portfolio.', 15)
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Cert 2 content loaded successfully.';
END $$;

-- ============================================================
-- CERT 3: USDA RMAP Eligibility, Application & Scoring
-- ============================================================
DO $$
DECLARE
  cert_id uuid; m1 uuid; m2 uuid; m3 uuid; m4 uuid; m5 uuid; quiz_id uuid;
BEGIN
  SELECT id INTO cert_id FROM certifications WHERE cert_number = 3;
  IF cert_id IS NULL THEN RAISE NOTICE 'Cert 3 not found'; RETURN; END IF;

  UPDATE certifications SET status = 'approved', learning_outcomes = ARRAY[
    'Identify the five RMAP applicant pathways and select the correct pathway for your organization',
    'Assemble the complete common application with all required documents for the 45-point baseline section',
    'Calculate estimated scores for experienced, less-experienced, and TA-only microlender pathways',
    'Map evidence documents to specific scoring criteria using an evidence crosswalk',
    'Understand RMAP competition cycles and quarterly submission strategy'
  ] WHERE id = cert_id;

  INSERT INTO modules (id, certification_id, title, sort_order, status) VALUES
    (gen_random_uuid(), cert_id, 'RMAP Architecture and Pathways', 1, 'approved'),
    (gen_random_uuid(), cert_id, 'The Common Application — 45 Points', 2, 'approved'),
    (gen_random_uuid(), cert_id, 'Experienced Microlender Scoring', 3, 'approved'),
    (gen_random_uuid(), cert_id, 'Less-Experienced and TA-Only Pathways', 4, 'approved'),
    (gen_random_uuid(), cert_id, 'Submission Strategy and Competition', 5, 'approved')
  ON CONFLICT DO NOTHING;

  SELECT id INTO m1 FROM modules WHERE certification_id = cert_id AND sort_order = 1;
  SELECT id INTO m2 FROM modules WHERE certification_id = cert_id AND sort_order = 2;
  SELECT id INTO m3 FROM modules WHERE certification_id = cert_id AND sort_order = 3;
  SELECT id INTO m4 FROM modules WHERE certification_id = cert_id AND sort_order = 4;
  SELECT id INTO m5 FROM modules WHERE certification_id = cert_id AND sort_order = 5;

  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m1, 'The Five RMAP Pathways — Which One Is Yours?', 'cert03-rmap-pathways',
  E'## RMAP Is Not One Application — It Is Five\n\nThe Rural Microentrepreneur Assistance Program has five distinct applicant pathways. Each pathway has different scoring criteria, different required documents, and different maximum point totals. Selecting the wrong pathway is one of the most common RMAP application errors.\n\n## The Five Pathways\n\n| Pathway | Experience Required | Funding Requested | Application Sections |\n|---------|--------------------|--------------------|---------------------|\n| 1 — Experienced + RMRF + TA Grant | More than 3 years microlending | Both loan and TA grant | Pages 2, 3, 4, 5 |\n| 2 — Experienced + RMRF Only | More than 3 years microlending | Loan only, no TA | Pages 2, 3, 4, 5 |\n| 3 — Less-Experienced + RMRF + TA | 3 years or fewer microlending | Both loan and TA grant | Pages 2, 3, 6 |\n| 4 — Less-Experienced + RMRF Only | 3 years or fewer microlending | Loan only, no TA | Pages 2, 3, 6 |\n| 5 — TA Only | Other capital sources for lending | TA grant only | Pages 2, 3, 7 |\n\nA sixth pathway exists for **reapplication** after 5 years of RMAP participation (page 8).\n\n## How to Determine Your Pathway\n\n**Step 1:** Do you currently make microloans to rural microentrepreneurs?\n- Yes → Are you applying for loan funds (RMRF) or TA grant or both?\n- No → Do you have other capital sources for lending (CDFIs, foundations, state programs)?\n  - Yes → Pathway 5 (TA Only)\n  - No → You may not yet be eligible as a microlender; consider Pathway 5 to build your track record\n\n**Step 2:** If you make microloans, how many years of history do you have?\n- More than 3 years of consecutive microlending → Pathways 1 or 2\n- 3 years or fewer → Pathways 3 or 4\n\n**The "3 years of experience" threshold is critical.** USDA measures experience by your actual lending history — specifically by whether you have microloan data for three consecutive Federal Fiscal Years immediately prior to application.\n\n## Why Pathway Selection Affects Your Score\n\nExperienced microlenders (Pathways 1 and 2) are scored under 4280.316(b) — which rewards actual microloan history data with up to 55 points. Less-experienced applicants (Pathways 3 and 4) are scored under 4280.316(c) — which instead rewards your work plan and capacity-building plan for up to 55 points.\n\nChoosing the wrong pathway (claiming experienced status when you have only 2 years of data) will result in a lower score because you cannot fill in the required three-year lending history tables.',
  'Identify the five RMAP pathways, select the correct one, and understand why pathway selection drives your score.', 16, 1, 'approved'),

  (m2, 'Section 4280.316(a) — The 45-Point Baseline', 'cert03-common-45-points',
  E'## Every RMAP Application Starts Here\n\nRegardless of pathway, every RMAP applicant must provide the information listed in 4280.316(a). This section has a maximum of **45 points** and is often called the "common application" or "baseline" section. Without strong baseline materials, you cannot score competitively regardless of your lending history.\n\n## The Seven Baseline Criteria\n\n### (a)(1) Organizational Chart — Up to 5 Points\nRequirement: Clearly showing positions and naming the individuals in those positions. Of particular interest: management positions and those essential to microlending and TA operations.\n\nWhat scores well: Every position named, not just titled. Key personnel clearly identified. Chart is current and matches resumes submitted.\n\nCommon mistake: Generic org chart templates with boxes but no names.\n\n### (a)(2) Resumes for Key Personnel — Up to 5 Points\nRequirement: Resumes for each individual shown on the org chart and indicated as key to RMAP operations. Points based on quality and demonstrated ability to administer the program.\n\nWhat scores well: Resumes that directly highlight microlending, TA delivery, federal program management, and rural community experience. Specific accomplishments (loans made, clients served, outcomes achieved) outperform generic job descriptions.\n\n### (a)(3) Succession Plan — Up to 5 Points\nRequirement: A plan to follow in the event of departure of key RMAP personnel.\n\nWhat scores well: Names specific backup personnel or describes the process for recruiting replacements. Shows the program will continue functioning if the executive director or loan officer leaves.\n\n### (a)(4) Policy & Procedures — Up to 5 Points\nRequirement: Parts of the policy and procedures manual dealing with loans, loan fund management, and TA.\n\nWhat scores well: A professional, detailed policy manual excerpted to the relevant sections. Policies that cover underwriting standards, loan committee authority, conflict of interest, servicing, and TA delivery.\n\n### (a)(5) Financial Statements — Up to 10 Points\nRequirement: Most recent and two prior years of financial statements.\n\nPoints based on: Demonstrated ability to maintain or grow fund balance, manage federal programs, and handle multiple funding sources (restricted and unrestricted).\n\nWhat scores well: Audited or reviewed statements showing financial health. A balance sheet with growing net assets. Evidence of prior federal grant management (grants receivable, deferred revenue). Multiple revenue sources.\n\n### (a)(6) Mission Statement — Up to 5 Points\nRequirement: Copy of the organization''s mission statement, rated on connectivity to microenterprise and economic development.\n\nWhat scores well: A mission statement with explicit language about microenterprise, economic development, rural communities, or capital access. If the mission statement is in bylaws, cite the document and page — do not submit bylaws twice.\n\n### (a)(7) Geographic Service Area — Up to 10 Points\nRequirement: Describe the rural service area, state the number of counties/jurisdictions, and demonstrate capacity to cover the area.\n\nWhat scores well: A specific, verifiable rural service area with census data confirming rural eligibility. Evidence of actual outreach in the named counties (existing loans, clients served). Staffing capacity that matches the geographic scale.\n\n## Building the Application Binder\n\nOrganize your application binder with clearly labeled tabs corresponding to each criterion. Each section should have:\n1. A brief cover page naming the criterion and your response\n2. The required document\n3. Any supporting attachments\n\nReviewers score dozens of applications. Clean organization signals professional capacity.',
  'Walk through all seven 4280.316(a) criteria with point values, what scores well, and common mistakes.', 20, 1, 'approved'),

  (m3, 'Experienced Microlender Scoring — 4280.316(b)', 'cert03-experienced-scoring',
  E'## The 55 Additional Points for Experienced Microlenders\n\nIf you have more than 3 years of microlending experience and are applying under Pathway 1 or 2, you will be scored under 4280.316(b) for an additional 55 points beyond the 45-point baseline. Total maximum: 100 points.\n\n## Criterion (b)(1): History of Provision of Microloans — Up to 20 Points\n\nThis is the most complex scoring criterion in the entire application. You must provide a data table (Figure 1 format) showing three consecutive Federal Fiscal Years immediately prior to your application.\n\n**The Figure 1 Table requires:**\n- Total number of microloans made (each of the 3 FFYs and total)\n- Total dollar amount of microloans made\n- Number made in rural areas\n- Dollar amount made in rural areas\n- Number made to racial and ethnic minorities\n- Number made to women\n- Number made to the disabled\n\n**Points are awarded across four sub-criteria:**\n\n**(b)(1)(i) Rural lending history — Up to 5 points:**\n- 3+ consecutive years of rural lending immediately prior: 5 points\n- At least 2 of the 3 consecutive years: 3 points\n- At least 6 months but less than 1 year: 1 point\n\n**(b)(1)(ii) Percentage of loans in rural areas (by count) — Up to 5 points:**\n- 75% or more: 5 points\n- 50-74%: 3 points\n- 25-49%: 1 point\n\n**(b)(1)(iii) Percentage of dollar amount in rural areas — Up to 5 points:**\n- 75% or more: 5 points\n- 50-74%: 3 points\n- 25-49%: 1 point\n\n**(b)(1)(iv) Demographic match — Up to 5 points:**\nCompare your portfolio demographics to your service area demographics (per latest decennial Census). Scored on how closely your lending mirrors the demographic makeup of your service area across gender, racial/ethnic minority status, and disability.\n- All groups within 5% of demographic makeup: 5 points\n- All groups within 10%: 3 points\n- One or more groups >10% off or missing: 1 point\n- Two or more groups missing entirely: 0 points\n\n## Criterion (b)(2): Portfolio Management — Up to 10 Points\n\nBased on on-time payment rate across your portfolio for the 3 prior Federal Fiscal Years:\n- 95% or more paying on time: 10 points\n- 85-95%: 7 points\n- 70-85%: 4 points\n- Below 70%: 0 points\n\n## Criteria (b)(3)–(b)(5): TA History, Commitment Letters, Work Plan\n- TA history and quality: Up to 10 points\n- Commitment/support letters: Up to 10 points\n- Work plan for proposed activities: Up to 5 points\n\n**Commitment letters** are a significant scoring opportunity. Strong letters come from: banks that refer clients to you, SBDCs that partner with you for TA, local governments that support your mission, and other CDFIs or RLF programs that coordinate with you. Letters should be specific — naming the proposed RMAP activities, not just general organizational endorsements.',
  'Master the 55-point experienced microlender scoring criteria including the Figure 1 data table and portfolio management.', 22, 1, 'approved'),

  (m4, 'Less-Experienced and TA-Only Pathway Scoring', 'cert03-lexi-ta-scoring',
  E'## Pathways 3-5: Building Credibility Without a Long Track Record\n\nFor organizations with fewer than 3 years of microlending experience — or those applying for TA grants only — USDA uses different scoring criteria that reward planning quality, organizational capacity, and partnership strength.\n\n## Less-Experienced Microlender Scoring — 4280.316(c) — Up to 55 Points\n\nThe centerpiece is a **5-page work plan** worth up to 20 points.\n\n**What makes a strong work plan:**\n- Specific microlending goals with numbers: how many loans, what size, what geographic area, what timeline\n- Staffing plan: who will originate loans, who will underwrite, who will serve on the loan committee\n- TA program description: how you will deliver TA to microborrowers, what types, how often\n- Outreach strategy: how you will find and reach eligible rural microentrepreneurs\n- Year 1, Year 2, Year 3 milestones with specific dates and deliverables\n\n**Additional scoring under (c):**\n- Years in business / organizational track record: Up to 10 points\n- Staffing and training plan: Up to 10 points\n- Support/commitment letters: Up to 10 points\n- Benchmarking against comparable programs: Up to 5 points\n\n**Benchmarking tip:** Research other RMAP microlenders — their loan volumes, TA approaches, and service areas. Use these as benchmarks for your projected Year 1 targets. Showing that your goals are realistic compared to similar organizations strengthens your credibility.\n\n## TA-Only Scoring — 4280.316(d) — Up to 55 Points\n\nTA-only applicants have other capital sources for lending and are seeking only the TA grant. Scoring focuses entirely on your TA history and plan.\n\n**Key criteria:**\n- TA history (3 prior years): Up to 20 points — document sessions, clients, methods, outcomes\n- Resultant microloans (TA-to-loan conversion): Up to 15 points — how many of your TA clients went on to receive microloans, from you or from other lenders\n- TA methods and delivery: Up to 10 points\n- Evaluation and outcome documentation: Up to 5 points\n- Proposed TA plan: Up to 5 points\n\n**The TA-to-loan conversion metric** is critical and often overlooked. USDA wants to see that your TA actually leads to capital access for microentrepreneurs. Track and document every referral from your TA program to a microlender, and record the loan amount and date.',
  'Understand Pathways 3-5 scoring: the 5-page work plan, capacity evidence, support letters, and TA-to-loan conversion.', 18, 1, 'approved'),

  (m5, 'RMAP Competition and Submission Strategy', 'cert03-submission-strategy',
  E'## RMAP Is a Competitive Program\n\nRMAP applications are scored and ranked nationally. USDA awards funding to the highest-scoring applications until available funds are exhausted. There is no guarantee of funding — even a well-prepared application may not receive an award in a highly competitive cycle.\n\n## Understanding the Competition Cycle\n\nRMAP accepts applications quarterly. Applications that do not receive funding in one quarter are carried over and reconsidered in up to four subsequent quarters. This four-quarter carryover provision means:\n- A strong application submitted in Q1 that does not receive Q1 funding may receive Q2, Q3, or Q4 funding\n- If not funded after four quarters, the application must be resubmitted\n- A minimum score threshold exists — applications below the threshold are not carried over\n\n## What "Minimum Score" Means in Practice\n\nUSDA establishes minimum scores periodically. Applications that do not meet the minimum are rejected and not carried over. While the specific minimum can change, historically competitive applications score above 70 points.\n\n## Submission Calendar Strategy\n\n**Start 6-12 months before your target submission:**\n- Month 1-2: Review your scoring gaps using a self-assessment against 4280.316\n- Month 3-4: Gather financial statements, update org chart and resumes, refine policies\n- Month 5-6: Collect commitment letters, compile microloan data table, complete TA documentation\n- Month 7-8: Draft all narrative sections, have an external reviewer read the binder\n- Month 9: Final review, assembly, and submission\n\n**The "organized packet" advantage:** USDA reviewers score dozens of applications. Applications that are clearly tabbed, concisely written, and directly responsive to each criterion stand out. Do not pad your binder with irrelevant documents.\n\n## Common Scoring Failures\n\n1. **Incomplete Figure 1 table** — Missing rural data or demographic data\n2. **Generic commitment letters** — Letters that do not specifically reference RMAP activities\n3. **Overclimbed service area** — Claiming 15 counties with staff for 2\n4. **Outdated financial statements** — Statements more than 12 months old at submission\n5. **Missing succession plan** — Required but frequently omitted\n6. **Policy manual not excerpted** — Submitting a 200-page manual instead of the relevant sections',
  'Plan your RMAP submission timeline, understand competition cycles, and avoid the most common scoring failures.', 15, 1, 'approved')

  ON CONFLICT DO NOTHING;

  INSERT INTO quizzes (id, certification_id, title, passing_score, status)
  VALUES (gen_random_uuid(), cert_id, 'RMAP Application & Scoring Knowledge Check', 80, 'approved')
  ON CONFLICT DO NOTHING;
  SELECT id INTO quiz_id FROM quizzes WHERE certification_id = cert_id;

  INSERT INTO quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES
  (quiz_id, 'Which RMAP pathway applies to an organization with 4 years of microlending experience applying for both a loan and a TA grant?', '[{"id":"a","text":"Pathway 3 — Less-experienced + RMRF + TA Grant"},{"id":"b","text":"Pathway 1 — Experienced + RMRF + TA Grant"},{"id":"c","text":"Pathway 5 — TA Only"},{"id":"d","text":"Pathway 4 — Less-experienced + RMRF Only"}]', 'b', 'More than 3 years of microlending experience qualifies as "experienced." Requesting both the RMRF loan and TA grant places this applicant in Pathway 1, scored under 4280.316(b).', 1),
  (quiz_id, 'The Figure 1 table in a 4280.316(b) application requires data for:', '[{"id":"a","text":"The current Federal Fiscal Year only"},{"id":"b","text":"The five years prior to the application"},{"id":"c","text":"Three consecutive Federal Fiscal Years immediately prior to the application"},{"id":"d","text":"Any three years of the organization''s choice"}]', 'c', 'The Figure 1 table requires data for the three consecutive Federal Fiscal Years immediately prior to the application. The years must be consecutive and immediately preceding — you cannot cherry-pick.', 2),
  (quiz_id, 'Under 4280.316(a)(7), USDA scores your geographic service area based on:', '[{"id":"a","text":"The total population of all counties in your service area"},{"id":"b","text":"Your ability to fully cover the service area you describe, not its size"},{"id":"c","text":"The percentage of rural residents in your service area"},{"id":"d","text":"Whether your service area spans multiple states"}]', 'b', 'USDA does not score on geographic size. The scoring is based on your demonstrated or planned capacity to serve the area described. A large service area you cannot staff scores worse than a small area you can serve well.', 3),
  (quiz_id, 'An experienced microlender''s portfolio shows 78% of loans made in rural areas by count. What score does this earn under 4280.316(b)(1)(ii)?', '[{"id":"a","text":"1 point"},{"id":"b","text":"3 points"},{"id":"c","text":"5 points"},{"id":"d","text":"0 points"}]', 'c', '75% or more of total microloans made in rural areas earns 5 points under 4280.316(b)(1)(ii). At 78%, this applicant earns the maximum 5 points for this sub-criterion.', 4),
  (quiz_id, 'What is the maximum number of points available in the 4280.316(a) common application section?', '[{"id":"a","text":"35 points"},{"id":"b","text":"45 points"},{"id":"c","text":"55 points"},{"id":"d","text":"100 points"}]', 'b', 'The common application section 4280.316(a) has a maximum of 45 points across 7 criteria. All applicants, regardless of pathway, compete for these 45 points.', 5),
  (quiz_id, 'A less-experienced microlender''s 5-page work plan is worth a maximum of:', '[{"id":"a","text":"5 points"},{"id":"b","text":"10 points"},{"id":"c","text":"20 points"},{"id":"d","text":"15 points"}]', 'c', 'Under 4280.316(c), the work plan (up to 5 pages) is worth up to 20 points — the single most valuable criterion in the less-experienced pathway. It must include specific goals, staffing, TA approach, outreach, and milestones.', 6),
  (quiz_id, 'RMAP applications that do not receive funding in the first quarter are:', '[{"id":"a","text":"Automatically rejected and must be resubmitted"},{"id":"b","text":"Carried over and reconsidered for up to four subsequent quarters"},{"id":"c","text":"Held pending additional documentation from the applicant"},{"id":"d","text":"Forwarded to the state rural development office for local funding"}]', 'b', 'RMAP has a four-quarter carryover provision. Applications that meet the minimum score but do not receive initial funding are reconsidered in subsequent quarters until the carryover period expires.', 7),
  (quiz_id, 'For TA-only applicants, which scoring criterion is worth the most points?', '[{"id":"a","text":"Proposed TA plan"},{"id":"b","text":"TA-to-loan conversion (resultant microloans)"},{"id":"c","text":"TA history over 3 prior years"},{"id":"d","text":"TA evaluation and outcome documentation"}]', 'c', 'Under 4280.316(d), TA history over the 3 prior years is worth up to 20 points — the highest single criterion for TA-only applicants. Resultant microloans are worth up to 15 points.', 8),
  (quiz_id, 'A strong commitment letter for an RMAP application should:', '[{"id":"a","text":"Be a generic letter of support praising the organization''s mission"},{"id":"b","text":"Come only from state and federal officials"},{"id":"c","text":"Specifically reference the proposed RMAP activities and describe the committing party''s role"},{"id":"d","text":"Be notarized to be counted"}]', 'c', 'Commitment letters score based on specificity and credibility. A strong letter names the proposed RMAP activities, describes what the signing organization will provide (referrals, TA partnership, etc.), and comes from a credible community partner.', 9),
  (quiz_id, 'What is the demographic match criterion in 4280.316(b)(1)(iv) measuring?', '[{"id":"a","text":"Whether the MDO''s staff matches its borrower demographics"},{"id":"b","text":"How closely the MDO''s microloan portfolio matches the demographic makeup of its service area"},{"id":"c","text":"Whether the MDO serves all racial groups equally"},{"id":"d","text":"Whether the MDO employs minority loan officers"}]', 'b', 'The demographic match criterion compares the MDO''s portfolio (by gender, racial/ethnic minority status, and disability) to the latest decennial Census data for the service area. The closer the match, the higher the score.', 10),
  (quiz_id, 'Which of the following is a common mistake in RMAP binder assembly?', '[{"id":"a","text":"Including too many commitment letters from community partners"},{"id":"b","text":"Submitting a 200-page policy manual instead of excerpting the relevant sections"},{"id":"c","text":"Using too many specific numbers and dates in the work plan"},{"id":"d","text":"Organizing the binder with clearly labeled tabs for each criterion"}]', 'b', 'Submitting the full policy manual is a common and costly mistake. Reviewers need the relevant excerpts, clearly identified and labeled — not a complete manual to search through. Excerpting signals professionalism and makes scoring easier.', 11),
  (quiz_id, 'What does a portfolio on-time payment rate of 96% earn under 4280.316(b)(2)?', '[{"id":"a","text":"7 points"},{"id":"b","text":"0 points"},{"id":"c","text":"10 points"},{"id":"d","text":"4 points"}]', 'c', '95% or more of microloans paying on time at the end of each of the prior three Federal Fiscal Years earns 10 points — the maximum for the portfolio management criterion.', 12),
  (quiz_id, 'An organization submitting its first RMAP application with 2 years of microlending history should use which scoring section?', '[{"id":"a","text":"4280.316(b) — Experienced microlender scoring"},{"id":"b","text":"4280.316(d) — TA-only scoring"},{"id":"c","text":"4280.316(c) — Less-experienced microlender scoring"},{"id":"d","text":"4280.316(e) — Reapplication scoring"}]', 'c', 'Two years of microlending history places the organization in the "3 years or fewer" category. This triggers 4280.316(c) scoring — the less-experienced pathway with its work plan focus.', 13),
  (quiz_id, 'The 4280.316(a)(5) financial statements criterion awards up to 10 points based on:', '[{"id":"a","text":"Whether statements are audited by a Big Four accounting firm"},{"id":"b","text":"Total revenue over the prior three years"},{"id":"c","text":"Demonstrated ability to maintain fund balance, manage federal programs, and handle multiple funding sources"},{"id":"d","text":"The organization''s credit rating"}]', 'c', 'Points are awarded based on the financial statements showing three things: (1) the ability to maintain or grow fund balance, (2) the ability to manage federal programs, and (3) capacity to handle multiple restricted and unrestricted funding sources.', 14),
  (quiz_id, 'How far in advance should an organization begin preparing a competitive RMAP application?', '[{"id":"a","text":"2-4 weeks before the quarterly deadline"},{"id":"b","text":"1-2 months before submission"},{"id":"c","text":"6-12 months before the target submission cycle"},{"id":"d","text":"RMAP requires no preparation — just fill out the form"}]', 'c', 'A competitive RMAP application requires 6-12 months of preparation: gathering 3 years of financial statements, building the Figure 1 data table, collecting commitment letters, refining policies, and assembling a clean binder.', 15)
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Cert 3 content loaded.';
END $$;

-- ============================================================
-- CERT 4: RMAP Microlender Operations, Loan Closing & Compliance
-- ============================================================
DO $$
DECLARE
  cert_id uuid; m1 uuid; m2 uuid; m3 uuid; quiz_id uuid;
BEGIN
  SELECT id INTO cert_id FROM certifications WHERE cert_number = 4;
  IF cert_id IS NULL THEN RAISE NOTICE 'Cert 4 not found'; RETURN; END IF;

  UPDATE certifications SET status = 'approved', learning_outcomes = ARRAY[
    'Explain the post-selection process from letter of conditions through OGC concurrence and loan closing',
    'Set up a compliant RMRF and LLRF with proper account controls and USDA lien documentation',
    'Maintain required RMAP records, reporting, and agency access during program participation',
    'Structure compliant RMAP microloans within the regulatory term, rate, and amount limits',
    'Identify and screen ineligible loan uses under the RMAP regulation'
  ] WHERE id = cert_id;

  INSERT INTO modules (id, certification_id, title, sort_order, status) VALUES
    (gen_random_uuid(), cert_id, 'From Selection to Closing', 1, 'approved'),
    (gen_random_uuid(), cert_id, 'RMRF and LLRF Setup and Controls', 2, 'approved'),
    (gen_random_uuid(), cert_id, 'Ongoing Compliance and Oversight', 3, 'approved')
  ON CONFLICT DO NOTHING;

  SELECT id INTO m1 FROM modules WHERE certification_id = cert_id AND sort_order = 1;
  SELECT id INTO m2 FROM modules WHERE certification_id = cert_id AND sort_order = 2;
  SELECT id INTO m3 FROM modules WHERE certification_id = cert_id AND sort_order = 3;

  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m1, 'The Post-Selection Process — Conditions to Closing', 'cert04-selection-to-closing',
  E'## What Happens After USDA Selects You?\n\nReceiving a selection letter from USDA is not the same as receiving funding. Before money moves, you must work through a structured post-selection process that can take several months. Understanding this process prevents delays and protects your award.\n\n## Step 1 — Letter of Conditions\n\nUSDA issues a Letter of Conditions outlining everything you must do before the RMAP loan closes and funds are disbursed. Common conditions include:\n- Providing additional documentation (updated financials, insurance certificates, board resolutions)\n- Establishing the RMRF account and providing account information to USDA\n- Confirming the LLRF account is established with the required 5% balance\n- Executing a security agreement giving USDA a first lien on the RMRF\n- Completing any required legal entity verification\n\nYou must respond to every condition in writing, with documentation. Missing a condition delays your closing.\n\n## Step 2 — OGC Concurrence (Office of General Counsel)\n\nBefore a USDA rural development loan can close, the USDA Office of General Counsel (OGC) must review and concur with the closing package. OGC reviews:\n- Your organization''s legal authority to borrow and lend\n- The security agreement and USDA''s lien position\n- Compliance with applicable regulations\n- Any unusual legal issues identified during review\n\nOGC review typically takes 4-8 weeks. Complex transactions or organizations with unusual legal structures can take longer.\n\n## Step 3 — Closing Package and Loan Closing\n\nOnce OGC concurs, USDA prepares the closing package. You will sign:\n- The loan agreement (the primary legal document governing your RMAP loan)\n- The security agreement (giving USDA a first lien on the RMRF)\n- Related certificates and representations\n\nAfter execution, USDA disburses the RMRF funds into your established RMRF account. You are now an RMAP microlender.\n\n## Closing Timeline Expectations\n\n| Phase | Typical Duration |\n|-------|------------------|\n| Letter of Conditions response | 30-60 days |\n| OGC review | 4-8 weeks |\n| Closing package execution | 1-2 weeks |\n| Fund disbursement | 1-2 weeks after closing |\n| **Total from selection to funds** | **3-6 months** |\n\nPlan for this timeline in your work plan. Many first-time applicants are surprised that selection does not mean immediate access to funds.',
  'Understand the post-selection process: Letter of Conditions, OGC review, closing package, and fund disbursement timeline.', 16, 1, 'approved'),

  (m2, 'Setting Up Your RMRF and LLRF', 'cert04-rmrf-llrf-setup',
  E'## The Two Required RMAP Accounts\n\nEvery RMAP microlender must establish and maintain two separate, dedicated accounts:\n\n### 1. Rural Microloan Revolving Fund (RMRF)\n- **What it is:** An exclusive, interest-bearing account from which all RMAP microloans are disbursed and into which all repayments are deposited\n- **USDA lien:** USDA holds a first lien on the RMRF — meaning USDA''s claim on the account takes priority over all other creditors\n- **Exclusivity:** The RMRF must not be commingled with operating funds, other loan programs, or any non-RMAP capital\n- **Interest:** Interest earned on the RMRF balance may be used for program purposes as defined in your loan agreement\n\n### 2. Loan Loss Reserve Fund (LLRF)\n- **What it is:** A separate interest-bearing account maintained at not less than 5% of the total amount owed by the microlender to USDA\n- **Purpose:** Absorb delinquency losses — if a microborrower defaults and the RMRF is short, the LLRF covers the gap\n- **Maintenance:** You must maintain the 5% minimum continuously. If the balance falls below 5% due to a loss draw, you must replenish it\n- **Separate from RMRF:** The LLRF must be in a separate account — not a sub-account of the RMRF\n\n## Account Documentation Requirements\n\nWhen you establish these accounts, document:\n- Bank name, account number, account type\n- Opening balance and source of funds\n- The security agreement referencing the USDA lien\n- Board resolution authorizing the accounts (if required by your bylaws)\n\nProvide this documentation to USDA as part of your Letter of Conditions response.\n\n## The Multiple RMRF Option\n\nA microlender may establish multiple RMRFs — for example, one capitalized under the 25% project-level cost share option and another under the 25% RMRF-level option. Whichever option is selected for a given RMRF must apply to the entire RMRF and all loans made from it.\n\n## LLRF Calculation Example\n\nIf USDA has lent your organization $500,000 for your RMRF, and you have made $200,000 in microloans with $300,000 remaining:\n\nTotal owed to USDA: $500,000\nRequired LLRF (5%): $25,000\n\nAs you repay USDA principal (through microborrower repayments flowing to USDA), the total owed decreases, and your required LLRF minimum decreases accordingly.',
  'Establish and document the RMRF and LLRF with proper account controls, USDA lien requirements, and separation standards.', 15, 1, 'approved'),

  (m3, 'Ongoing Compliance, Reporting, and Oversight', 'cert04-ongoing-compliance',
  E'## Life as an Active RMAP Microlender\n\nOnce your RMRF is funded and you begin making microloans, you enter a continuous compliance cycle. USDA monitors active microlenders through required reports, annual certifications, and periodic site visits.\n\n## Required Reporting\n\n**Quarterly Reports:** USDA requires quarterly reporting on:\n- Microloan activity (loans made, amounts, borrower demographics, rural percentage)\n- TA activity (sessions delivered, clients served, outcomes)\n- Portfolio status (on-time payments, delinquencies, defaults, recoveries)\n- RMRF and LLRF balances\n\n**SF-270 for TA Grants:** If you received a TA grant, you must submit SF-270 (Request for Advance or Reimbursement) to draw TA grant funds, with supporting documentation of allowable TA expenses.\n\n**Annual Reports:** Year-end summary reports, audited financial statements, and certification of compliance with program requirements.\n\n## Agency Access Requirements\n\nYour RMAP loan agreement grants USDA the right to inspect your records and visit your office. You must:\n- Maintain all required records for the duration of the agreement plus record retention period (typically 3-7 years after program closeout)\n- Provide records to USDA upon request\n- Allow USDA staff to conduct site visits with reasonable notice\n- Cooperate fully with any program review or audit\n\n## Key Personnel Change Notifications\n\nIf a key person listed in your RMAP application leaves the organization — particularly the loan officer, executive director, or any person essential to RMAP operations — you must notify USDA promptly. USDA may require you to identify a qualified replacement as a condition of continued program participation.\n\n## Microloan File Requirements\n\nEvery RMAP microloan must have a complete loan file containing:\n- Borrower application\n- Credit analysis and underwriting memo\n- Loan committee minutes and decision\n- Executed loan documents (note, security agreement, any guaranty)\n- UCC financing statement (if collateral was pledged)\n- Credit elsewhere documentation\n- Insurance certificate (if required)\n- TA documentation (pre-loan TA completed)\n- Payment records\n- Correspondence and borrower contact records\n\n## Ineligible Uses — Know Before You Lend\n\nRMAP microloan funds cannot be used for:\n- **Residential housing** construction or rehabilitation, even if used partly for business\n- **Revolving lines of credit** — microloans must be for a defined purpose\n- **Agricultural production** (unless meeting the microenterprise definition)\n- **Insider loans** — officers, directors, employees, or family members of the MDO\n- **Religious activities** where that is the primary purpose\n- **Gambling** or any illegal activity\n- **Businesses outside your eligible rural service area**\n\nDocument your ineligible use screen for every application as part of your loan file.',
  'Maintain RMAP compliance: quarterly reporting, agency access, key personnel notifications, loan file requirements, and ineligible use screening.', 18, 1, 'approved')

  ON CONFLICT DO NOTHING;

  INSERT INTO quizzes (id, certification_id, title, passing_score, status)
  VALUES (gen_random_uuid(), cert_id, 'RMAP Operations & Compliance Knowledge Check', 80, 'approved')
  ON CONFLICT DO NOTHING;
  SELECT id INTO quiz_id FROM quizzes WHERE certification_id = cert_id;

  INSERT INTO quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES
  (quiz_id, 'After receiving a USDA RMAP selection letter, what is the typical total timeline from selection to fund disbursement?', '[{"id":"a","text":"1-2 weeks"},{"id":"b","text":"1 month"},{"id":"c","text":"3-6 months"},{"id":"d","text":"12-18 months"}]', 'c', 'The post-selection process — responding to conditions, OGC review, closing, and disbursement — typically takes 3-6 months. First-time applicants often underestimate this timeline.', 1),
  (quiz_id, 'What is the primary purpose of OGC review in the RMAP closing process?', '[{"id":"a","text":"To verify the borrower''s creditworthiness"},{"id":"b","text":"To review the legal documents and USDA''s security position before the loan closes"},{"id":"c","text":"To audit the organization''s financial statements"},{"id":"d","text":"To approve the organization''s loan underwriting standards"}]', 'b', 'The USDA Office of General Counsel reviews the legal closing package — the security agreement, USDA''s lien position, and the organization''s legal authority — before funds are disbursed.', 2),
  (quiz_id, 'The LLRF must be maintained at a minimum balance of:', '[{"id":"a","text":"2% of the total RMRF balance"},{"id":"b","text":"5% of the total amount owed by the microlender to USDA"},{"id":"c","text":"10% of annual loan originations"},{"id":"d","text":"$25,000 regardless of portfolio size"}]', 'b', 'The LLRF must be maintained at not less than 5% of the total amount owed to USDA. This minimum is calculated on the outstanding USDA loan balance, not the RMRF balance.', 3),
  (quiz_id, 'Which of the following is an INELIGIBLE use of RMAP microloan funds?', '[{"id":"a","text":"Equipment purchase for a rural food truck"},{"id":"b","text":"Working capital for a rural childcare center"},{"id":"c","text":"A revolving line of credit for a rural landscaping business"},{"id":"d","text":"Leasehold improvements for a rural hair salon"}]', 'c', 'Revolving lines of credit are ineligible under RMAP. Microloans must be for a defined purpose. Equipment, working capital, and leasehold improvements for rural businesses are all eligible uses.', 4),
  (quiz_id, 'An RMAP microlender must notify USDA when:', '[{"id":"a","text":"A microborrower pays off their loan early"},{"id":"b","text":"The organization updates its website"},{"id":"c","text":"A key person essential to RMAP operations leaves the organization"},{"id":"d","text":"The organization opens a new office location"}]', 'c', 'USDA must be notified when key personnel named in the RMAP application depart. USDA may require identification of a qualified replacement as a condition of continued participation.', 5),
  (quiz_id, 'RMAP microloans must have a FIXED interest rate because:', '[{"id":"a","text":"Fixed rates are required by 7 CFR 4280 as a borrower protection"},{"id":"b","text":"Variable rates are not available for loans under $50,000"},{"id":"c","text":"USDA sets the rate for each loan individually"},{"id":"d","text":"Fixed rates are required only for loans over $25,000"}]', 'a', 'Fixed rates are required by the RMAP regulation as a borrower protection. Rural microentrepreneurs on thin margins cannot absorb rate volatility. The fixed rate requirement also aligns with USDA''s own fixed-rate lending to the microlender.', 6),
  (quiz_id, 'The RMRF must be:', '[{"id":"a","text":"A checking account at any bank the microlender chooses"},{"id":"b","text":"An exclusive interest-bearing account with USDA holding a first lien, not commingled with other funds"},{"id":"c","text":"Managed by a state-appointed trustee"},{"id":"d","text":"Deposited at a USDA-approved bank only"}]', 'b', 'The RMRF must be exclusive (used only for RMAP microloans), interest-bearing, and subject to USDA''s first lien. Commingling with operating funds or other loan programs is prohibited.', 7),
  (quiz_id, 'RMAP TA grant funds must be drawn using which form?', '[{"id":"a","text":"SF-424"},{"id":"b","text":"SF-270"},{"id":"c","text":"RD 1910-11"},{"id":"d","text":"400-8v5"}]', 'b', 'SF-270 (Request for Advance or Reimbursement) is used to draw RMAP TA grant funds. It must be supported by documentation of allowable TA expenses.', 8),
  (quiz_id, 'A loan to a board member of the MDO using RMAP funds would be:', '[{"id":"a","text":"Allowed if the board member recuses from the loan committee decision"},{"id":"b","text":"Allowed up to $25,000"},{"id":"c","text":"Ineligible — insider loans are prohibited under RMAP"},{"id":"d","text":"Allowed with USDA pre-approval"}]', 'c', 'Loans to officers, directors, employees, or family members of the MDO are ineligible uses of RMAP microloan funds. This prohibition exists regardless of the loan committee process.', 9),
  (quiz_id, 'How long must RMAP records be retained after program closeout?', '[{"id":"a","text":"1 year"},{"id":"b","text":"3-7 years (depending on the program agreement)"},{"id":"c","text":"10 years"},{"id":"d","text":"Indefinitely"}]', 'b', 'Record retention requirements for USDA programs are typically 3-7 years after program closeout, as specified in the RMAP loan agreement and 2 CFR 200. Check your specific agreement for the applicable period.', 10),
  (quiz_id, 'Which document in the microloan file proves the borrower could not obtain credit from a conventional source?', '[{"id":"a","text":"The loan committee minutes"},{"id":"b","text":"The UCC financing statement"},{"id":"c","text":"The credit elsewhere documentation"},{"id":"d","text":"The SF-424"}]', 'c', 'Credit elsewhere documentation — typically a certification by the borrower and/or a denial letter from a conventional lender — is required to demonstrate that the borrower cannot obtain sufficient credit from conventional sources, as required by RMAP statute.', 11),
  (quiz_id, 'A microlender establishes a second RMRF using the project-level cost share option. What does this mean for individual microloans from this RMRF?', '[{"id":"a","text":"Each microloan may finance up to 100% of the borrower''s project cost"},{"id":"b","text":"Each microloan may finance no more than 75% of the borrower''s project cost; the borrower provides 25% from non-federal sources"},{"id":"c","text":"The second RMRF must be capitalized with 100% USDA funds"},{"id":"d","text":"Loans from the second RMRF are not subject to the $50,000 cap"}]', 'b', 'Under the project-level cost share option, each individual microloan is capped at 75% of the eligible project cost. The borrower must obtain the remaining 25% from non-federal sources (cash, grants, in-kind).', 12),
  (quiz_id, 'USDA quarterly reports for RMAP must include:', '[{"id":"a","text":"Only financial statements"},{"id":"b","text":"Microloan activity, TA activity, portfolio status, and RMRF/LLRF balances"},{"id":"c","text":"Only the number of loans made in the quarter"},{"id":"d","text":"A copy of every executed loan document"}]', 'b', 'RMAP quarterly reports must cover microloan activity (loans made, demographics, rural %), TA activity (sessions, clients, outcomes), portfolio status (delinquencies, defaults), and account balances for the RMRF and LLRF.', 13),
  (quiz_id, 'What is the maximum term for an RMAP microloan?', '[{"id":"a","text":"5 years"},{"id":"b","text":"7 years"},{"id":"c","text":"10 years"},{"id":"d","text":"20 years"}]', 'c', 'RMAP microloans have a maximum term of 10 years. This applies regardless of the loan purpose.', 14),
  (quiz_id, 'Which of the following must be in every RMAP microloan file?', '[{"id":"a","text":"Audited financial statements for the borrower"},{"id":"b","text":"A personal credit score printout"},{"id":"c","text":"Executed loan documents, credit analysis, TA documentation, and credit elsewhere documentation"},{"id":"d","text":"A notarized affidavit from the loan committee chair"}]', 'c', 'Every RMAP microloan file must include executed loan documents, the credit analysis and underwriting memo, documentation of pre-loan TA completed, and credit elsewhere documentation. Personal credit scores are reviewed during underwriting but the analysis memo is the required file document.', 15)
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Cert 4 content loaded.';
END $$;

-- ============================================================
-- CERT 5: RMAP Technical Assistance & Training Program
-- ============================================================
DO $$
DECLARE
  cert_id uuid; m1 uuid; m2 uuid; m3 uuid; m4 uuid; quiz_id uuid;
BEGIN
  SELECT id INTO cert_id FROM certifications WHERE cert_number = 5;
  IF cert_id IS NULL THEN RAISE NOTICE 'Cert 5 not found'; RETURN; END IF;

  UPDATE certifications SET status = 'approved', learning_outcomes = ARRAY[
    'Design a TA program structure aligned with both RMAP scoring requirements and borrower success outcomes',
    'Build comprehensive TA documentation systems including logs, evaluations, and outcome tracking',
    'Calculate and document TA-to-loan conversion rates for RMAP scoring purposes',
    'Budget allowable TA grant activities and complete SF-270 draw requests',
    'Create a 90-day TA program launch plan with measurable targets'
  ] WHERE id = cert_id;

  INSERT INTO modules (id, certification_id, title, sort_order, status) VALUES
    (gen_random_uuid(), cert_id, 'TA Program Strategy and Design', 1, 'approved'),
    (gen_random_uuid(), cert_id, 'TA Documentation Systems', 2, 'approved'),
    (gen_random_uuid(), cert_id, 'TA Outcomes and Evaluation', 3, 'approved'),
    (gen_random_uuid(), cert_id, 'TA Grant Budget and Reporting', 4, 'approved')
  ON CONFLICT DO NOTHING;

  SELECT id INTO m1 FROM modules WHERE certification_id = cert_id AND sort_order = 1;
  SELECT id INTO m2 FROM modules WHERE certification_id = cert_id AND sort_order = 2;
  SELECT id INTO m3 FROM modules WHERE certification_id = cert_id AND sort_order = 3;
  SELECT id INTO m4 FROM modules WHERE certification_id = cert_id AND sort_order = 4;

  INSERT INTO lessons (module_id, title, slug, content, summary, read_time_minutes, sort_order, status) VALUES
  (m1, 'Designing Your RMAP TA Program', 'cert05-ta-program-design',
  E'## Why TA Is Central to RMAP — Not Optional\n\nUnder USDA RMAP, technical assistance is not a program feature — it is a regulatory requirement. Every microlender must provide integrated TA and training to its microborrowers and prospective microborrowers. For TA-only MDOs, TA is the entire program.\n\nBeyond compliance, research consistently shows: microloan programs that pair TA with lending achieve significantly lower default rates than programs that lend without support. The TA-loan combination is what the model is designed around.\n\n## Types of TA Delivery\n\n**Individual counseling (1-on-1):** The most intensive and highest-scoring delivery method. A business advisor works directly with one borrower on their specific situation: business plan development, financial projections, cash flow analysis, permit navigation.\n\n**Group training:** Workshops and seminars on business planning, financial literacy, marketing, and USDA program basics. More efficient per client but lower intensity.\n\n**Peer learning groups:** Connecting borrowers with each other to share challenges, solutions, and accountability. Research shows peer groups improve business survival rates.\n\n**Distance/online learning:** Webinars, recorded tutorials, and online courses. Especially valuable in rural areas where travel to in-person training is a barrier.\n\n## TA Before and After the Loan\n\nRMAP requires TA for both prospective and existing microborrowers:\n\n**Pre-loan TA:** Business readiness assessment, business plan development, financial projection building, permit and licensing navigation. Pre-loan TA reduces default by ensuring borrowers are ready.\n\n**Post-loan TA:** Ongoing check-ins, annual reviews, problem-solving when challenges arise. Post-loan TA catches early warning signs before they become delinquency.\n\n## Building Your TA Service Catalog\n\nA service catalog documents exactly what TA you offer:\n\n| Service | Format | Duration | Target Audience |\n|---------|--------|----------|-----------------|\n| Business plan development | 1-on-1 | 4-8 hours | Pre-loan applicants |\n| Financial literacy workshop | Group | 3 hours | All clients |\n| Cash flow modeling | 1-on-1 | 2 hours | Loan-ready applicants |\n| Quarterly business review | 1-on-1 | 1 hour | Active borrowers |\n| Peer accountability group | Group | 1.5 hours/month | All clients |\n\nA documented service catalog supports your RMAP application by demonstrating a structured, professional TA program.',
  'Design a compliant, effective RMAP TA program covering delivery methods, pre/post-loan TA, and service catalog.', 16, 1, 'approved'),

  (m2, 'TA Documentation — The Log and the Loan File', 'cert05-ta-documentation',
  E'## Why Every Session Must Be Documented\n\nTA documentation serves three critical purposes:\n1. **RMAP compliance:** USDA requires documentation of all TA activities as a condition of the program\n2. **Scoring evidence:** Future RMAP applications score your TA history — but only the history you can document\n3. **Program improvement:** Good documentation reveals which TA approaches lead to better borrower outcomes\n\n## The TA Session Log — Required Fields\n\nEvery TA session — individual or group — must be logged with:\n\n- **Date of session**\n- **Client name(s)** (or anonymized ID if privacy required)\n- **Session format** (individual, group, webinar, phone)\n- **Topics covered** (specific: "cash flow projection for Year 1" not just "finances")\n- **Duration** (hours and minutes)\n- **Objectives** (what was the client expected to learn or do?)\n- **Outcomes** (what did the client accomplish during or after the session?)\n- **Referrals made** (to SBDC, SCORE, other TA providers, lenders)\n- **Next steps** (what action is the client taking before the next session?)\n- **Advisor signature**\n\n## Group Training Documentation\n\nFor group workshops and seminars, document:\n- Date, location, topic, duration\n- Attendance roster with signatures (or registration records for virtual events)\n- Training materials (agenda, handouts, slide deck)\n- Participant evaluation form (collected at end of session)\n- Number of participants by demographic (for RMAP reporting)\n\n## Linking TA Records to the Loan File\n\nEvery RMAP microloan file should reference the TA provided to that borrower before the loan:\n- Date and duration of pre-loan TA sessions\n- Topics covered\n- Business plan or projections developed during TA\n- Assessment of borrower readiness based on TA engagement\n\nThis linkage demonstrates the integrated TA-lending model USDA requires and supports your portfolio quality claims in future applications.',
  'Build a complete TA documentation system: session logs, group training records, and linking TA to the loan file.', 15, 1, 'approved'),

  (m3, 'TA Outcomes, Evaluations, and Success Stories', 'cert05-ta-outcomes',
  E'## What Outcomes Must You Track?\n\nRMAP TA-only applicants are scored on outcomes (resultant microloans, business survival, jobs). All microlenders should track outcomes to improve their programs and build evidence for future applications.\n\n## Core Outcome Metrics\n\n**TA-to-loan conversion:** How many TA clients went on to receive a microloan from your program (or from another lender you referred them to)? Track:\n- Number of TA clients who received microloans\n- Dollar amount of those microloans\n- Time between TA start and loan closing\n\nFor TA-only applicants under 4280.316(d), this metric is worth up to 15 points.\n\n**Business survival rate:** Are clients still in business 12 months after receiving TA? Measure by following up at 6 months and 12 months.\n\n**Revenue growth:** Self-reported revenue change from baseline to 12 months. Collect at intake and at annual follow-up.\n\n**Jobs created and retained:** Number of FTE jobs created or maintained by TA clients. This is a USDA priority metric.\n\n**Repayment rate:** For borrowers who received both TA and loans, what is their on-time payment rate compared to non-TA borrowers? This data argues directly for the value of integrated TA.\n\n## The Evaluation Form\n\nCollect a short satisfaction evaluation at the end of each TA engagement:\n- Overall satisfaction (1-5 scale)\n- Most valuable aspect of TA\n- What would improve the service\n- Whether the client would recommend the program\n- Contact information for 12-month follow-up\n\n## Writing Effective Success Stories\n\nSuccess stories are powerful in RMAP applications and marketing:\n\n**Structure:**\n1. **The challenge:** What was the client''s situation before TA? (Rural, underserved, specific barrier)\n2. **The TA provided:** What specific services did you deliver?\n3. **The outcome:** Loan received, revenue generated, jobs created, business launched\n4. **The numbers:** Always include specific metrics — not "sales improved" but "monthly revenue increased from $3,000 to $8,500 in 12 months"\n\nCollect one quality success story per quarter. Build a bank of 10-20 stories that cover diverse borrower demographics and business types.',
  'Track TA outcomes: conversion rates, business survival, revenue growth, jobs created. Write effective success stories with specific metrics.', 15, 1, 'approved'),

  (m4, 'TA Grant Budget and SF-270 Reporting', 'cert05-ta-budget',
  E'## TA Grant Allowable Costs\n\nRMAP TA grants can be used to pay for costs directly related to delivering TA and training to rural microentrepreneurs. Allowable costs under most USDA TA grant agreements include:\n\n**Direct costs:**\n- Staff time (salary and benefits proportional to time spent on RMAP TA activities)\n- Contracted TA providers (SBDCs, SCORE, independent consultants)\n- Training materials (curriculum, handouts, workbooks)\n- Technology (software for business plan development, financial modeling tools)\n- Travel for TA delivery (mileage, lodging if required)\n- Event costs for group training (room rental, materials)\n\n**Indirect costs:**\n- A negotiated indirect cost rate (IDC) or 10% de minimis rate under 2 CFR 200.414\n- Covers organizational overhead: accounting, HR, facilities, insurance\n\n## The Administrative Cost Percentage\n\nUSDA TA grants typically cap administrative costs as a percentage of total grant activity. Review your specific grant agreement for the applicable percentage. If no cap is stated, the 2 CFR 200 de minimis indirect cost rate (10% of modified total direct costs) is available to organizations without a negotiated rate.\n\n## Drawing TA Grant Funds — The SF-270\n\nTo draw funds from your RMAP TA grant, you submit an SF-270 (Request for Advance or Reimbursement) to your USDA state office.\n\n**Required supporting documentation:**\n- Time sheets showing staff hours attributed to RMAP TA activities\n- Invoices for contracted services\n- Receipts for direct costs\n- Activity logs demonstrating the TA was delivered\n\n**Frequency:** Most microlenders draw TA grant funds quarterly, aligned with their quarterly activity reports.\n\n## Quarterly Narrative Report\n\nAlongside the SF-270, USDA requires a quarterly narrative report covering:\n- TA sessions delivered (count by type)\n- Clients served (unduplicated count, demographics)\n- Outcomes achieved (loans made, businesses launched, jobs created)\n- Challenges encountered and how addressed\n- Next quarter goals\n\nKeep narrative reports factual and specific. "We delivered 47 TA sessions to 23 clients, resulting in 8 loan applications and 5 approved loans totaling $185,000" is far stronger than "we provided significant TA support to rural entrepreneurs."',
  'Budget allowable TA costs, complete SF-270 draw requests, and write quarterly narrative reports with specific outcome data.', 14, 1, 'approved')

  ON CONFLICT DO NOTHING;

  INSERT INTO quizzes (id, certification_id, title, passing_score, status)
  VALUES (gen_random_uuid(), cert_id, 'RMAP Technical Assistance Knowledge Check', 80, 'approved')
  ON CONFLICT DO NOTHING;
  SELECT id INTO quiz_id FROM quizzes WHERE certification_id = cert_id;

  INSERT INTO quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES
  (quiz_id, 'Under RMAP, technical assistance is:', '[{"id":"a","text":"Optional — only required if the microlender chooses to offer it"},{"id":"b","text":"Required — every microlender must provide integrated TA to microborrowers and prospective microborrowers"},{"id":"c","text":"Required only for TA-only MDOs"},{"id":"d","text":"Required only for first-time borrowers"}]', 'b', 'RMAP requires every microlender to provide integrated TA and training to microborrowers and prospective microborrowers. TA is a regulatory requirement, not an optional enhancement.', 1),
  (quiz_id, 'The TA-to-loan conversion metric in 4280.316(d) scoring is worth up to:', '[{"id":"a","text":"5 points"},{"id":"b","text":"10 points"},{"id":"c","text":"15 points"},{"id":"d","text":"20 points"}]', 'c', 'Under 4280.316(d), resultant microloans (TA-to-loan conversion) are worth up to 15 points. This is the second-highest single criterion for TA-only applicants, behind TA history (20 points).', 2),
  (quiz_id, 'Which of the following MUST be documented in a TA session log?', '[{"id":"a","text":"The client''s personal credit score"},{"id":"b","text":"Date, format, topics, duration, outcomes, and next steps"},{"id":"c","text":"The client''s bank account information"},{"id":"d","text":"A notarized attendance confirmation"}]', 'b', 'A complete TA session log must include date, session format, topics covered, duration, objectives, outcomes achieved, referrals made, and next steps. This documentation is required for USDA compliance and future application scoring.', 3),
  (quiz_id, 'To draw RMAP TA grant funds, a microlender submits:', '[{"id":"a","text":"SF-424"},{"id":"b","text":"SF-270"},{"id":"c","text":"RD 1910-11"},{"id":"d","text":"A simple invoice to USDA"}]', 'b', 'SF-270 (Request for Advance or Reimbursement) is the form used to draw RMAP TA grant funds, supported by documentation of allowable TA expenses.', 4),
  (quiz_id, 'What does the 10% de minimis indirect cost rate under 2 CFR 200.414 allow?', '[{"id":"a","text":"Organizations to skip indirect cost documentation entirely"},{"id":"b","text":"Organizations without a negotiated IDC rate to charge 10% of modified total direct costs for overhead"},{"id":"c","text":"Organizations to charge up to 10% of gross revenue as administrative costs"},{"id":"d","text":"Organizations to redirect 10% of grant funds to unrestricted purposes"}]', 'b', 'The 2 CFR 200 de minimis rate allows organizations that have never negotiated an indirect cost rate to charge 10% of modified total direct costs to cover overhead (facilities, accounting, HR, etc.) without additional justification.', 5),
  (quiz_id, 'A strong success story for RMAP purposes should include:', '[{"id":"a","text":"The borrower''s full name and address for verification"},{"id":"b","text":"Specific numbers: revenue amounts, jobs created, loan amount — not just general statements"},{"id":"c","text":"A comparison to competitors in the same industry"},{"id":"d","text":"Testimony from USDA staff endorsing the program"}]', 'b', 'Success stories should always include specific metrics — revenue before and after, jobs created, loan amount, timeline. "Monthly revenue increased from $3,000 to $8,500 in 12 months" is far stronger than general statements about improvement.', 6),
  (quiz_id, 'Pre-loan TA is important because:', '[{"id":"a","text":"It is required before any RMAP loan can be approved"},{"id":"b","text":"It ensures borrowers are ready before receiving capital, reducing default risk"},{"id":"c","text":"It replaces the credit analysis process"},{"id":"d","text":"It allows the loan committee to waive collateral requirements"}]', 'b', 'Pre-loan TA builds borrower readiness — business plans, financial projections, operational systems. Borrowers who receive TA before their loans have consistently lower default rates than those who do not.', 7),
  (quiz_id, 'How often should RMAP microlenders follow up with TA clients to measure outcomes?', '[{"id":"a","text":"Only at the time of loan closing"},{"id":"b","text":"At 6 months and 12 months after TA engagement"},{"id":"c","text":"Only if the client contacts the MDO first"},{"id":"d","text":"Every 5 years"}]', 'b', 'Best practice and effective outcome tracking requires follow-up at 6 months and 12 months after TA engagement to measure business survival, revenue growth, and jobs created or retained.', 8),
  (quiz_id, 'Which TA delivery format is typically most effective for complex individual business challenges?', '[{"id":"a","text":"Group workshop"},{"id":"b","text":"Online webinar"},{"id":"c","text":"Individual 1-on-1 counseling"},{"id":"d","text":"Peer learning group"}]', 'c', 'Individual 1-on-1 counseling is the most intensive delivery method and most effective for complex, individualized business challenges — though it is also the most resource-intensive. A strong TA program uses a mix of all formats.', 9),
  (quiz_id, 'RMAP TA grants allow paying for which of the following?', '[{"id":"a","text":"Staff salaries for time spent on fundraising for other programs"},{"id":"b","text":"Capital to make microloans"},{"id":"c","text":"Staff time, contracted TA providers, training materials, and direct TA delivery costs"},{"id":"d","text":"Marketing and advertising for the MDO"}]', 'c', 'Allowable TA grant costs include staff time proportional to TA work, contracted TA providers, training materials, and direct delivery costs. Capital for microloans, fundraising for other programs, and general marketing are not allowable.', 10),
  (quiz_id, 'For group training documentation, which is REQUIRED?', '[{"id":"a","text":"A notarized attendance list"},{"id":"b","text":"An attendance roster, training materials, and participant evaluations"},{"id":"c","text":"Individual follow-up reports for every participant"},{"id":"d","text":"A copy of the trainer''s professional license"}]', 'b', 'Group training documentation requires: an attendance roster (with signatures or registration records), training materials (agenda/handouts), and participant evaluations collected at the end of the session.', 11),
  (quiz_id, 'What does an effective quarterly TA narrative report include?', '[{"id":"a","text":"Only the number of clients served"},{"id":"b","text":"TA sessions by type, unduplicated client count with demographics, outcomes achieved, challenges, and next quarter goals"},{"id":"c","text":"A copy of every TA session log"},{"id":"d","text":"Financial statements for the quarter"}]', 'b', 'Quarterly TA narrative reports must cover session counts by type, unduplicated client demographics, specific outcomes (loans made, businesses launched, jobs), challenges encountered, and goals for the next quarter.', 12),
  (quiz_id, 'Peer learning groups as a TA delivery method are valuable because:', '[{"id":"a","text":"They eliminate the need for individual counseling"},{"id":"b","text":"They are cheaper than individual counseling and still improve business survival rates"},{"id":"c","text":"They are required by USDA for all TA programs"},{"id":"d","text":"They count triple in RMAP TA history scoring"}]', 'b', 'Peer learning groups are cost-efficient relative to individual counseling and research shows they improve business survival rates through shared accountability, peer problem-solving, and network building.', 13),
  (quiz_id, 'The TA-to-loan conversion tracking requires documenting:', '[{"id":"a","text":"Only loans made directly by the MDO''s own RLF"},{"id":"b","text":"Loans made to TA clients by the MDO or any other lender the MDO referred the client to"},{"id":"c","text":"All loans in the MDO''s service area regardless of TA connection"},{"id":"d","text":"Only loans made after the RMAP TA grant was awarded"}]', 'b', 'TA-to-loan conversion includes loans to your TA clients from ANY source — your own RLF or lenders you referred clients to. Tracking and documenting all loan outcomes from TA clients demonstrates the full impact of your TA program.', 14),
  (quiz_id, 'A TA program service catalog should document:', '[{"id":"a","text":"Only the services offered to loan applicants"},{"id":"b","text":"Each TA service, its format, duration, and target audience"},{"id":"c","text":"The names of all TA clients served in the prior year"},{"id":"d","text":"The budget for each TA activity"}]', 'b', 'A service catalog documents each TA service offered: the specific service name, delivery format (1-on-1, group, online), duration, and target audience. This demonstrates a structured program in RMAP applications.', 15)
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Cert 5 content loaded.';
END $$;
